-- 0013_pricing: generated by `pnpm db:generate --name=pricing`; the guards at the end are hand-written
-- (ADR-0024 #2, ADR-0041). Applied migrations are never edited.
CREATE TABLE "discount_programs" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "discount_programs_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"name" text NOT NULL,
	"list" text NOT NULL,
	"scope" text NOT NULL,
	"measure" text NOT NULL,
	"effect" text NOT NULL,
	"product_id" bigint,
	"product_unit_id" bigint,
	"threshold_unit_id" bigint,
	"category_id" bigint,
	"count_uom_id" bigint,
	"valid_from" date NOT NULL,
	"valid_to" date,
	"created_by" bigint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "discount_programs_name" CHECK (length("discount_programs"."name") BETWEEN 1 AND 120),
	CONSTRAINT "discount_programs_list" CHECK ("discount_programs"."list" IN ('WHOLESALE', 'RETAIL')),
	CONSTRAINT "discount_programs_scope" CHECK ("discount_programs"."scope" IN ('PRODUCT', 'CATEGORY', 'ORDER')),
	CONSTRAINT "discount_programs_measure" CHECK ("discount_programs"."measure" IN ('QTY', 'AMOUNT')),
	CONSTRAINT "discount_programs_effect" CHECK ("discount_programs"."effect" IN ('PRICE', 'PERCENT', 'AMOUNT')),
	CONSTRAINT "discount_programs_shape" CHECK (("discount_programs"."scope" = 'PRODUCT' AND "discount_programs"."product_id" IS NOT NULL AND "discount_programs"."category_id" IS NULL
          AND "discount_programs"."count_uom_id" IS NULL AND "discount_programs"."measure" = 'QTY'
          AND ("discount_programs"."effect" = 'PERCENT' OR "discount_programs"."product_unit_id" IS NOT NULL))
        OR ("discount_programs"."scope" = 'CATEGORY' AND "discount_programs"."category_id" IS NOT NULL AND "discount_programs"."product_id" IS NULL
          AND "discount_programs"."product_unit_id" IS NULL AND "discount_programs"."threshold_unit_id" IS NULL AND "discount_programs"."effect" <> 'PRICE'
          AND ("discount_programs"."measure" = 'QTY') = ("discount_programs"."count_uom_id" IS NOT NULL))
        OR ("discount_programs"."scope" = 'ORDER' AND "discount_programs"."product_id" IS NULL AND "discount_programs"."product_unit_id" IS NULL
          AND "discount_programs"."threshold_unit_id" IS NULL AND "discount_programs"."category_id" IS NULL AND "discount_programs"."count_uom_id" IS NULL
          AND "discount_programs"."measure" = 'AMOUNT' AND "discount_programs"."effect" <> 'PRICE')),
	CONSTRAINT "discount_programs_validity" CHECK ("discount_programs"."valid_to" IS NULL OR "discount_programs"."valid_to" >= "discount_programs"."valid_from")
);
--> statement-breakpoint
