-- Hand-written: a unit has one price per list on any day (ADR-0041 #1). btree_gist (0000) lets the
-- text and bigint columns join the date range; a row closed on its first day has an empty range.
ALTER TABLE "unit_prices" ADD CONSTRAINT "unit_prices_no_overlap"
  EXCLUDE USING gist ("list" WITH =, "product_unit_id" WITH =, daterange("valid_from", "valid_to", '[)') WITH &&);
--> statement-breakpoint

-- Hand-written: a price's history is never rewritten. Only valid_to moves, and only earlier
-- (closing a row, or voiding one that has not started); the service never closes a row before
-- the business date. created_by may still be cleared when a user is deleted.
CREATE FUNCTION unit_prices_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.list IS DISTINCT FROM OLD.list
     OR NEW.product_unit_id IS DISTINCT FROM OLD.product_unit_id OR NEW.price IS DISTINCT FROM OLD.price
     OR NEW.valid_from IS DISTINCT FROM OLD.valid_from OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (OLD.valid_to IS NOT NULL AND (NEW.valid_to IS NULL OR NEW.valid_to > OLD.valid_to)) THEN
    RAISE EXCEPTION 'unit_prices %: only valid_to may change, and only to an earlier date', OLD.id
      USING ERRCODE = 'restrict_violation';  -- 23001
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER "unit_prices_guard" BEFORE UPDATE ON "unit_prices"
  FOR EACH ROW EXECUTE FUNCTION unit_prices_guard();
--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "unit_prices" FROM app;
--> statement-breakpoint

-- Hand-written: at most one PRICE program per unit and list on any day, so a cart never has to
-- choose between two new prices (ADR-0041 #2); the other effects stack.
ALTER TABLE "discount_programs" ADD CONSTRAINT "discount_programs_one_price"
  EXCLUDE USING gist ("list" WITH =, "product_unit_id" WITH =, daterange("valid_from", "valid_to", '[)') WITH &&)
  WHERE ("effect" = 'PRICE');
